   116:        Self { kind: SynthesizedKind(SynthesizedKind::NAMED.to_string()), value: value.into() }
   117:    }
   118:    pub fn contract(method: &str, path: &str) -> Self {
   119:        Self {
   120:            kind: SynthesizedKind(SynthesizedKind::CONTRACT_ID.to_string()),
   121:            value: format!("{} {}", method.to_uppercase(), path),
   122:        }
   123:    }
   124:    /// 用于数据库唯一索引与跨规则比对的字符串形式。
   125:    pub fn key(&self) -> String {
   126:        format!("{}:{}", self.kind, self.value)
   127:    }
