   129:    /// 仅对 `ContractId` 有效：拆出 `(METHOD, /path)`。
   130:    ///
   131:    /// 身份值为 `"{METHOD} {path}"`（见 [`IdentityKey::contract`]），
   132:    /// method 已是大写；path 不含空格。
   133:    pub fn contract_parts(&self) -> Option<(String, String)> {
   134:        if self.kind.as_str() != SynthesizedKind::CONTRACT_ID {
   135:            return None;
   136:        }
   137:        let mut it = self.value.splitn(2, ' ');
   138:        let method = it.next()?;
   139:        let path = it.next()?;
   140:        Some((method.to_string(), path.to_string()))
   141:    }
   142:}
