   261:        </Descriptions.Item>
   262:        {edge.indirect ? (
   263:          <Descriptions.Item label={t('性质')}>
   264:            <Space size={4}>
   265:              <Tag color="gold">{t('间接（沿调用链传播）')}</Tag>
   266:              <Tooltip title={t('indirect.tooltip')}>
   267:                <InfoCircleOutlined style={{ color: '#d48806', cursor: 'help' }} />
   268:              </Tooltip>
   269:            </Space>
   270:          </Descriptions.Item>
   271:        ) : null}
   272:        <Descriptions.Item label={t('置信度')}>{edge.confidence.toFixed(2)}</Descriptions.Item>
   273:        {edge.hops !== null ? (
   274:          <Descriptions.Item label={t('跳数')}>{t('途经 ') + edge.hops + t(' 跳')}</Descriptions.Item>
   275:        ) : null}
   276:      </Descriptions>
   277:
   278:      {showChain ? (
   279:        <CollapsedChain
   280:          edge={edge}
   281:          via={via}
   282:          paths={[via]}
   283:          nodeNameOf={nodeNameOf}
   284:          projectRoot={projectRoot}
   285:          wslDistro={wslDistro}
   286:          onNodeClick={onNodeClick}
   287:        />
   288:      ) : null}
   289:
   290:      {data?.reason ? <Alert type="warning" showIcon message={data.reason} /> : null}
   291:
   292:      {unresolved && !chainCoversProof ? (
   293:        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
   294:          {t('未解析的边是推断结果：下面每个位置都是可亲自验证的落点，核对后再采信。')}
   295:        </Typography.Text>
   296:      ) : null}
   297:
   298:      {data && data.via.length > 0 ? (
   299:        <Space direction="vertical" size={4}>
   300:          {data.via.map((v, i) => (
   301:            <Tag key={i}>{v}</Tag>
   302:          ))}
   303:        </Space>
   304:      ) : null}
   305:
   306:      {/* 链路已把每一跳的调用处逐条列出（直达边的 `to_call_site` 也在其中），raw 边的位置是其子集，
   307:          无需重复展示；只在链路没给出本边那一行时显示。 */}
   308:      {evidenceLocations.length > 0 && !chainCoversProof ? (
   309:        <div>
   310:          <Typography.Text strong style={{ fontSize: 13 }}>
   311:            {t('证据位置')}
   312:          </Typography.Text>
   313:          <div style={{ marginTop: 8 }}>
   314:            <LocationList
   315:              locations={evidenceLocations}
   316:              ordered
   317:              projectRoot={projectRoot}
   318:              wslDistro={wslDistro}
   319:              emptyHint={t('这条边没有可跳转的证据位置（可能来自权威源推断）')}
   320:            />
   321:          </div>
   322:        </div>
   323:      ) : null}
   324:    </Space>
   325:  );
   326:}
   327:
   328:/**
   329: * 调用链：把这条边按 起点 → 中间各跳 → 终点（语义节点）逐跳列出。
   330: *
   331: * 折叠提拉边在图上看似直连，其实是一条多跳调用链被折叠后的结果；被折掉的中间节点只存在于
   332: * **当次视图结果**（`EdgeView.via`）里，按边 id 重查是拿不到的 —— 所以必须由点击方随身带入。
   333: * via 节点只带 id/kind/name，因此每一跳的源码位置要按节点 id 现查，才能给出真正的"调用处"。
   334: *
   335: * **直达语义边**（`via` 为空，如 `save --投递到--> 队列`）也走这里：只有 起点/终点 两跳，
   336: * 中间那一行取自边的 `to_call_site`。这样"点边看链"在两种情形下是同一套版式 ——
   337: * 都能看见起点是谁、终点是哪个语义节点，而不是只剩一行孤立的位置。
   338: */
   339:function CollapsedChain({
   340:  edge,
   341:  via,
   342:  paths,
   343:  nodeNameOf,
   344:  projectRoot,
   345:  wslDistro,
   346:  onNodeClick,
   347:}: {
   348:  edge: EdgeView;
   349:  /** 兼容旧调用：单条路径。 */
   350:  via?: ViaNode[];
   351:  /** 多条路径（优先）；缺省用 `via` 包成单条。路由到表常有多条调用路径（如直查 `value` 与主列表 `getGoodsList`），用此字段呈现分叉。 */
   352:  paths?: ViaNode[][];
   353:  nodeNameOf?: (id: number) => string;
   354:  projectRoot?: string;
   355:  wslDistro?: string;
   356:  /** 点击某跳的节点名 → 在主图中以该节点为中心重绘。 */
   357:  onNodeClick?: (id: number) => void;
   358:}) {
   359:  const { t } = useLocale();
   360:  const name = (id: number) => nodeNameOf?.(id) ?? `#${id}`;
   361:  const pathList = paths && paths.length > 0 ? paths : via ? [via] : [];
   362:
   363:  // 所有路径上的节点都要取位置（含起止），避免第一跳"调用处"断头。
   364:  const allIds = useMemo(() => {
   365:    const s = new Set<number>([edge.from, edge.to]);
   366:    pathList.forEach((p) => p.forEach((v) => s.add(v.id)));
   367:    return [...s];
   368:  }, [pathList, edge.from, edge.to]);
   369:
   370:  // 存整个 `NodeLocations`：需要 `synthetic` 来决定如何标注"定义处"。
   371:  // 共享节点（ConfigKey / Table / Cache …）由同键多处共现合成，
   372:  // 它的**全部出处并不都属于当前链路** —— 混着展示会让人以为链路串到了无关文件。
   373:  //
   374:  // 优先用后端**内联**在 `edge.node_locations` 里的位置（折叠视图链路是临时提拉的，
   375:  // 中间跳按边 id 重查不到，所以后端一次给全）。只对缺失的节点回退到原接口，
   376:  // 避免对每一跳都发一次 `/nodes/{id}/locations`（N+1）。
   377:  const inline = useMemo(() => {
   378:    const m: Record<number, NodeLocations> = {};
   379:    for (const e of edge.node_locations ?? []) {
   380:      m[e.id] = {
   381:        id: e.id,
   382:        kind: '',
   383:        name: '',
   384:        synthetic: e.synthetic,
   385:        locations: e.locations,
   386:        reference_count: 0,
   387:      };
   388:    }
   389:    return m;
   390:  }, [edge.node_locations]);
   391:
   392:  const missingKey = allIds.filter((id) => !(id in inline)).join(',');
   393:
   394:  const [fetched, setFetched] = useState<Record<number, NodeLocations>>({});
   395:  useEffect(() => {
   396:    const missing = missingKey ? missingKey.split(',').map(Number) : [];
   397:    if (missing.length === 0) return;
   398:    let alive = true;
   399:    void Promise.all(
   400:      missing.map((id) =>
   401:        viewApi
   402:          .nodeLocations(id)
   403:          .then((r) => [id, r] as const)
   404:          .catch(() => [id, null] as const),
   405:      ),
   406:    ).then((pairs) => {
   407:      if (!alive) return;
   408:      const next: Record<number, NodeLocations> = {};
   409:      for (const [id, r] of pairs) {
   410:        if (r) next[id] = r;
   411:      }
   412:      setFetched(next);
   413:    });
   414:    return () => {
   415:      alive = false;
   416:    };
   417:  }, [missingKey]);
   418:
   419:  // 内联数据优先；仅补上后端没有内联的节点。
   420:  const locs = useMemo(() => ({ ...fetched, ...inline }), [fetched, inline]);
   421:
   422:  type Step = {
   423:    key: string;
   424:    id: number;
   425:    kind: string | null;
   426:    name: string;
   427:    role: string | null;
   428:    locations: SourceLocation[];
   429:    callSite: SourceLocation | null;
   430:  };
   431:
   432:  // 单条位置的紧凑渲染：只保留 `file:line · symbol` 与（可选）snippet。
   433:  // 相比 `LocationList` 的整块灰卡，去掉外框与重复按钮，让链路每一跳更轻。
   434:  // `symbol` 是机器合成的全限定名（如 `A::b#C::d:252`），与上方 `Tag + 节点名` 重复，
   435:  // 且会让一行路径换行参差；改为只在悬停时显示（`note` 同理），可见行只保留 `file:line` + 可选 snippet。
   436:  const locationNode = (loc: SourceLocation) => {
   437:    const tip = [loc.note, loc.symbol].filter(Boolean).join(' · ');
   438:    const title = loc.file + ':' + loc.line + (tip ? ' — ' + tip : '');
   439:    return (
   440:      <div style={{ minWidth: 0 }}>
   441:        <Tooltip title={title}>
   442:          <Typography.Link
   443:            style={{ fontSize: 12, wordBreak: 'break-all' }}
   444:            onClick={() => void copyPath(loc, projectRoot)}
   445:          >
   446:            {loc.file}:{loc.line}
   447:          </Typography.Link>
   448:        </Tooltip>
   449:        {loc.snippet ? (
   450:        <pre
   451:          style={{
   452:            margin: '4px 0 0',
   453:            padding: '4px 8px',
   454:            fontSize: 11,
   455:            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
   456:            background: '#f6f8fa',
   457:            borderRadius: 6,
   458:            color: '#475569',
   459:            whiteSpace: 'pre-wrap',
   460:            wordBreak: 'break-all',
   461:            maxHeight: 120,
   462:            overflow: 'auto',
   463:          }}
   464:        >
   465:          {loc.snippet}
   466:        </pre>
   467:      ) : null}
   468:      </div>
   469:    );
   470:  };
   471:
   472:  // 这是「边链路视图」（点边打开），只应展示与本边相关（on-path）的位置，**绝不**展示资源在全代码库的
   473:  // 共现足迹（"全部出处 N 处"）。资源的完整足迹属于「点节点」场景（NodePanel / LocationList），
   474:  // 在边证据链里出现会让人误以为 N 处都在链上——其实只有 1 处在链上，其余只是「同类共现」。
   475:  //  - 非终点：节点自身定义处（s.locations[0]），即链路途经的方法 / 类位置；
   476:  //  - 终点：本边到达它的那一行（s.callSite = edge.to_call_site），即上一跳调用它的位置
   477:  //    （它已在上一行的调用语句里显示过，这里再给一个复制按钮方便跳转）。
   478:  const definitionButton = (s: Step): ReactNode => {
   479:    if (s.locations.length === 0 && !s.callSite) return null;
   480:    const onPath = s.role === '终点' ? s.callSite ?? s.locations[0] : s.locations[0];
   481:    if (!onPath) return null;
   482:    const tip = [onPath.note, onPath.symbol].filter(Boolean).join(' · ');
   483:    return (
   484:      <Tooltip title={tip || t('复制 path:line')}>
   485:        <Button
   486:          size="small"
   487:          type="text"
   488:          icon={<CopyOutlined />}
   489:          style={{ fontSize: 11, flexShrink: 0 }}
   490:          onClick={() => void copyPath(onPath, projectRoot)}
   491:        />
   492:      </Tooltip>
   493:    );
   494:  };
   495:
   496:  const stepDescription = (s: Step, nextCallSite?: SourceLocation | null, prevNextCallSite?: SourceLocation | null): ReactNode => {
   497:    // 调用方归属：cs = 本节点体内「调下一跳」的那一行（即下一跳的 call_site，指向本节点文件内），
   498:    // 与被调方的「定义处」同属一个文件，读起来是「route 调 detail / detail 调 tidyOrder …」的自然叙述。
   499:    // 定义处已提到节点名右侧的「定义」按钮（见 definitionButton），这里只保留调用语句这一主干。
   500:    const cs = nextCallSite;
   501:    const isEnd = s.role === '终点';
   502:
   503:    const rows: ReactNode[] = [];
   504:    // 与上一行「调用语句」同址时不重复渲染（如 相邻两跳恰好落在同一 file:line）。
   505:    const dupCallSite =
   506:      !!prevNextCallSite && !!cs && prevNextCallSite.file === cs.file && prevNextCallSite.line === cs.line;
   507:    if (cs && !dupCallSite) {
   508:      rows.push(<Fragment key="cs">{locationNode(cs)}</Fragment>);
   509:    } else if (!isEnd && !cs) {
   510:      // 非终点却拿不到「调下一跳」的调用语句：该跳不是直接的 `Calls` 边（如 路由→handler 的绑定，或调用未解析），
   511:      // 后端 `call_site_between` 两种来源都落空。如实标注，避免调用链在这里看起来莫名断掉。
   512:      rows.push(
   513:        <Typography.Text
   514:          key="cs"
   515:          type="secondary"
   516:          title={t('该跳不是直接的 Calls 边（如 路由→handler 的绑定，或调用未解析），后端未给出「调用处」')}
   517:          style={{ fontSize: 11 }}
   518:        >
   519:          {t('未解析到调用语句')}
   520:        </Typography.Text>,
   521:      );
   522:    }
   523:    if (rows.length === 0) return null;
   524:
   525:    // 统一缩进到与节点名同列（NAME_INDENT），调用语句的 file:line / snippet 上下对齐。
   526:    return (
   527:      <div style={{ paddingLeft: NAME_INDENT }}>
   528:        <Space direction="vertical" size={SP.row} style={{ width: '100%' }}>
   529:          {rows}
   530:        </Space>
   531:      </div>
   532:    );
   533:  };
   534:
   535:  const renderPath = (p: ViaNode[]) => {
   536:    const steps: Step[] = [
   537:      { key: `from-${edge.from}`, id: edge.from, kind: null, name: name(edge.from), role: '起点', locations: locs[edge.from]?.locations ?? [], callSite: null },
   538:      ...p.map((v) => ({
   539:        key: `via-${v.id}`,
   540:        id: v.id,
   541:        kind: v.kind,
   542:        name: v.name,
   543:        role: null as string | null,
   544:        locations: locs[v.id]?.locations ?? [],
   545:        callSite: v.call_site ?? null,
   546:      })),
   547:      { key: `to-${edge.to}`, id: edge.to, kind: null, name: name(edge.to), role: '终点', locations: locs[edge.to]?.locations ?? [], callSite: edge.to_call_site ?? null },
   548:    ];
   549:    return (
   550:      <Timeline
   551:        items={steps.map((s, i) => ({
   552:          color: TIMELINE_DOT_COLOR,
   553:          children: (
   554:            <div style={{ marginBottom: SP.step }}>
   555:              {(() => {
   556:                const isEndpoint = !s.kind;
   557:                // 端点（起点/终点）用描边淡标签：白底 + 彩边 + 彩字，与中间节点「按 kind 实心填充」分层、不抢眼。
   558:                const stroke = isEndpoint
   559:                  ? s.role === '起点'
   560:                    ? '#16a34a'
   561:                    : s.role === '终点'
   562:                      ? '#dc2626'
   563:                      : '#1677ff'
   564:                  : '#1677ff';
   565:                return (
   566:                  <Space size={SP.tagGap} wrap style={{ rowGap: 2 }}>
   567:                    <Tag
   568:                      color={isEndpoint ? undefined : nodeColor(s.kind ?? '')}
   569:                      style={{
   570:                        ...(isEndpoint
   571:                          ? { backgroundColor: '#fff', borderColor: stroke, color: stroke }
   572:                          : { color: '#fff' }),
   573:                        minWidth: 64,
   574:                        margin: 0,
   575:                        textAlign: 'center',
   576:                      }}
   577:                    >
   578:                      {s.kind ?? t(s.role ?? '')}
   579:                    </Tag>
   580:                    {/* 节点名走中性近黑，不跟着 Tag 上色：颜色额度只留两处 —— Tag（kind 色）与文件名（可跳转的蓝 Link）。
   581:                        否则绿起点 / 蓝 Method / 红终点 + 蓝文件名，一屏全是颜色。可点性由加粗与悬停提示表达。 */}
   582:                    <Typography.Link
   583:                      style={{ fontSize: 13, fontWeight: 600, wordBreak: 'break-all', color: NODE_NAME_COLOR }}
   584:                      onClick={() => onNodeClick?.(s.id)}
   585:                      title={t('在主图中以该节点为中心重绘')}
   586:                    >
   587:                      {s.name}
   588:                    </Typography.Link>
   589:                    {definitionButton(s)}
   590:                  </Space>
   591:                );
   592:              })()}
   593:              {/* 调用语句归属调用方：行 i 展示「本节点体内调下一跳」的那一行，故传入下一跳的 callSite；
   594:                  终点无下一跳，自然只留定义处。上一行的 nextCallSite 用于同址去重。 */}
   595:              <div style={{ marginTop: SP.row }}>{stepDescription(s, i < steps.length - 1 ? steps[i + 1].callSite : null, i > 0 ? steps[i].callSite : null)}</div>
   596:            </div>
   597:          ),
   598:        }))}
   599:      />
   600:    );
   601:  };
   602:
   603:  if (pathList.length === 0) return null;
   604:
   605:  return (
   606:    <div>
   607:      <Typography.Text strong style={{ fontSize: 13 }}>
   608:        {/* 有中间跳被折掉才叫「折叠掉的调用链」；直达边只有 起点↔终点 两跳，标题如实写「调用链」，
   609:            版式与路由链路完全一致。 */}
   610:        {t(pathList.some((p) => p.length > 0) ? '折叠掉的调用链' : '调用链')}
   611:        {/* 多路径时保留条数汇总（有用）；单路径的"跳数"已由顶部 Descriptions 的「跳数」给出，这里不再重复。 */}
   612:        {pathList.length > 1 ? `（${pathList.length}${t(' 条路径')}）` : null}
   613:      </Typography.Text>
   614:      {/* 标题与下方第一个节点之间留出呼吸间隙，避免标题贴住时间线圆点。 */}
   615:      <div style={{ marginTop: SP.section }}>
   616:        {pathList.length === 1 ? (
   617:          renderPath(pathList[0])
   618:        ) : (
   619:          <Collapse
   620:            defaultActiveKey={['0']}
   621:            size="small"
   622:            items={pathList.map((p, idx) => ({
   623:              key: String(idx),
   624:              label: `${t('路径 ') + (idx + 1)}`,
   625:              children: renderPath(p),
   626:            }))}
   627:          />
   628:        )}
   629:      </div>
   630:    </div>
   631:  );
   632:}
