  1340:                        // 已覆盖节点即命中。必须穷举所有上游分支——只跟第一条会漏掉并行分支
  1341:                        // （如 controller 类同时被 `HandledBy→路由` 与 `Declares→文件` 连接，
  1342:                        // 或 mapper 同时被 `Calls→service` 与 `Declares→接口` 连接）。
  1343:                        let mut frontier: Vec<i64> = vec![start];
  1344:                        let mut seen: HashSet<i64> = HashSet::new();
  1345:                        for _ in 0..64 {
  1346:                            if frontier.is_empty() {
