  1399:                                    for e in ins {
  1400:                                        if matches!(
  1401:                                            e.kind.as_str(),
  1402:                                            "Calls" | "HandledBy" | "Declares"
  1403:                                        ) {
  1404:                                            nxt.push(e.from_id.get());
  1405:                                        }
  1406:                                    }
  1407:                                }
  1408:                            }
  1409:                            frontier = nxt;
  1410:                        }
  1411:                        false
  1412:                    };
  1413:                    let mut collapsed: Vec<i64> = d
  1414:                        .ring_of
  1415:                        .keys()
  1416:                        .copied()
  1417:                        .filter(|id| {
  1418:                            *id != center_id.get()
  1419:                                && d.parent_of.get(id) == Some(&center_id.get())
  1420:                                && !d.semantic_of.get(id).copied().unwrap_or(false)
  1421:                                && !covered.contains(id)
