{"requestId":"7d25e5e9ac034c1f8546e656e8a79652","modelId":"hy3","modelName":"Hy3","isHelperMessage":false,"traceId":"e76c1087492fb6adeaa4ee89506243e7","toolStatus":{"call_88c7139a8c0740e88ff59048":{"ready":true,"status":"executed","args":{"filePath":"/home/alvin/graphtell/graphtell/crates/gt-application/src/view_service.rs","offset":440,"limit":140},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"/home/alvin/graphtell/graphtell/crates/gt-application/src/view_service.rs","content":"   440:
   441:    /// 发现阶段：以中心为起点沿**调用链**做分层 BFS，产出折叠视图所需的全部状态。
   442:    ///
   443:    /// 见 `Discovery` 的文档：这一阶段结束后状态即冻结，后续只读。
   444:    #[allow(clippy::too_many_arguments)]
   445:    fn discover(
   446:        &self,
   447:        center_id: NodeId,
   448:        center_node: &gt_domain::model::Node,
   449:        chain_depth: u32,
   450:        reverse: bool,
   451:        library_subs: &HashSet<i64>,
   452:        summary: &HashMap<i64, NodeSummary>,
   453:        sem_of: &dyn Fn(i64) -> bool,
   454:    ) -> Result<Discovery> {
   455:        let sub_of =
   456:            |id: i64| -> i64 { summary.get(&id).and_then(|m| m.sub_project_id).unwrap_or(0) };
   457:        let mut ring_of: HashMap<i64, u32> = HashMap::new();
   458:        let mut parent_of: HashMap<i64, i64> = HashMap::new();
   459:        let mut kind_of: HashMap<i64, String> = HashMap::new();
   460:        let mut name_of: HashMap<i64, String> = HashMap::new();
   461:        let mut semantic_of: HashMap<i64, bool> = HashMap::new();
   462:        // 边缓存：BFS 与后续「提拉 / 原样保留边」共享，避免对同一节点反复 `edges_of` 往返。
   463:        let mut out_edges: HashMap<i64, Vec<gt_domain::model::Edge>> = HashMap::new();
   464:        let mut in_edges: HashMap<i64, Vec<gt_domain::model::Edge>> = HashMap::new();
   465:
   466:        // 事件 / 队列 / 缓存等中介节点：其直接生产方（`Triggers` 入边）与消费方
   467:        // （`HandledBy` / `PublishesTo` 出边）通常不是第一类语义节点（而是
   468:        // `event('x')` 调用点或被 `listener` 标注的类）。
   469:        // 画布恒为语义节点（语法节点默认折叠、在抽屉 / Inspector 展开查看），
   470:        // 所以这里**只**把它们种入第 1 环用于发现遍历与资源边提拉，并**不再强制可见**——
   471:        // 它们会作为「直连访问」降级进 `orphans` 记账（带接触点位置），而非画成画布节点。
   472:        let force_visible: HashSet<i64> = HashSet::new();
   473:        // 反向模式：从中心走到该节点途中遇到的**语义边种类**（即"资源被怎样访问"）。
   474:        let mut path_kind: HashMap<i64, String> = HashMap::new();
   475:        // 与 `path_kind` 平行：走到该节点途中遇到的语义边**是否为传播得来的间接边**。
   476:        // 资源视角（"谁在读这个配置"）同样要能区分直接读者与"上游读过"的间接入口。
   477:        let mut path_indirect: HashMap<i64, bool> = HashMap::new();
   478:        // 与 `path_kind` 平行：这条原始边是**中心 → 该节点**（中心为出边的一侧）。
   479:        // 反向模式默认画「使用者 --语义边--> 中心」，这对主语在使用者的边（Triggers /
   480:        // ReadsDb …）是对的；但 `HandledBy` 的主语是**中心自己**（`事件 --由…处理--> 监听器`、
   481:        // `契约 --由…处理--> handler`），它是中心的出边，照默认方向画就颠倒了谓语。
   482:        let mut path_from_center: HashSet<i64> = HashSet::new();
   483:        // 每个节点在本层择优时胜出的**边 id**：用于「边 id 小者优先」的确定性兜底比较。
   484:        let mut best_edge_id_of: HashMap<i64, i64> = HashMap::new();
   485:        kind_of.insert(center_id.get(), center_node.kind.to_string());
   486:        name_of.insert(center_id.get(), center_node.name.clone());
   487:        semantic_of.insert(center_id.get(), node_is_semantic(&center_node));
   488:        ring_of.insert(center_id.get(), 0);
   489:
   490:        // 按层批量取边（分块 `IN` 查询），写入边缓存。
   491:        let fetch_edges = |ids: &[i64],
   492:                           out: &mut HashMap<i64, Vec<gt_domain::model::Edge>>,
   493:                           inc: &mut HashMap<i64, Vec<gt_domain::model::Edge>>|
   494:         -> Result<()> {
   495:            if ids.is_empty() {
   496:                return Ok(());
   497:            }
   498:            let nids: Vec<NodeId> = ids.iter().map(|i| NodeId(*i)).collect();
   499:            let outs = self.store.edges_outgoing(&nids)?;
   500:            let ins = self.store.edges_incoming(&nids)?;
   501:            for (k, v) in outs {
   502:                out.entry(k).or_insert(v);
   503:            }
   504:            for (k, v) in ins {
   505:                inc.entry(k).or_insert(v);
   506:            }
   507:            Ok(())
   508:        };
   509:
   510:        // 预取中心节点的双向边（Event 播种 / 正向播种 / 第 0 层展开都要用）。
   511:        fetch_edges(&[center_id.get()], &mut out_edges, &mut in_edges)?;
   512:
   513:        if matches!(center_node.kind.as_str(), "Event" | "Queue" | "Topic") {
   514:            let outs = out_edges.get(&center_id.get()).cloned().unwrap_or_default();
   515:            let ins = in_edges.get(&center_id.get()).cloned().unwrap_or_default();
   516:            for e in outs.iter().chain(ins.iter()) {
   517:                if !matches!(e.kind.as_str(), "Triggers" | "HandledBy" | "PublishesTo") {
   518:                    continue;
   519:                }
   520:                let center_side = e.from_id.get() == center_id.get();
   521:                let other = if center_side {
   522:                    e.to_id.get()
   523:                } else {
   524:                    e.from_id.get()
   525:                };
   526:                if other == center_id.get() {
   527:                    continue;
   528:                }
   529:                path_kind.entry(other).or_insert(e.kind.to_string());
   530:                // 中心的**出边**（如 `事件 --HandledBy--> 监听器`）：画边时不能反过来。
   531:                if center_side {
   532:                    path_from_center.insert(other);
   533:                }
   534:                if !ring_of.contains_key(&other) {
   535:                    ring_of.insert(other, 1);
   536:                    parent_of.insert(other, center_id.get());
   537:                    // 消费者（`HandledBy` 的监听器 / `PublishesTo` 的消费者）是**稳定的命名角色**
   538:                    // （一个监听器类只处理一类事件），与 handler 不同：升为可见语义节点画在画布上，
   539:                    // 其 `HandledBy` 边也顺势成为可点击、可展开调用链的语义边。
   540:                    // 触发者（`Triggers` 的 dispatch 调用点）仍是任意业务方法、fan-in 高，
   541:                    // 不升节点、留作"直连访问"记账（下方 `collapsed_from` 会附上可展开的语义边）。
   542:                    let is_consumer =
   543:                        e.kind.as_str() == "HandledBy" || e.kind.as_str() == "PublishesTo";
   544:                    semantic_of.insert(other, is_consumer);
   545:                }
   546:                // 不再 `force_visible`：触发方（语法方法）不画成画布节点，
   547:                // 由下方 `collapsed_from` 分支降级进 `orphans` 记账（附可点击展开的语义边）。
   548:            }
   549:        }
   550:
   551:        // 正向模式：把"中心的入向链邻居"也作为第 1 环（表 / 外部系统视角需要）。
   552:        // 这些第 1 环节点要在第 1 层与中心的孩子一起展开。
   553:        let mut seed_ring1: Vec<i64> = Vec::new();
   554:        if !reverse {
   555:            if let Some(inc) = in_edges.get(&center_id.get()) {
   556:                for e in inc {
   557:                    if !is_chain_edge(e.kind.as_str()) {
   558:                        continue;
   559:                    }
   560:                    let other = e.from_id.get();
   561:                    if other == center_id.get() || ring_of.contains_key(&other) {
   562:                        continue;
   563:                    }
   564:                    ring_of.insert(other, 1);
   565:                    parent_of.insert(other, center_id.get());
   566:                    seed_ring1.push(other);
   567:                }
   568:            }
   569:        }
   570:
   571:        // 分层 BFS：每层一次性批量取边，把原来「每节点一次 edges_of 往返」压成几次分块查询；
