    /// 入边回溯（监听器 / 服务方法都挂在某个 `Class` 上）。
    fn method_qualified_name(
        &self,
        method: i64,
        d: &Discovery,
        summary: &HashMap<i64, NodeSummary>,
    ) -> String {
        let raw = d
            .name_of
            .get(&method)
            .cloned()
            .or_else(|| summary.get(&method).map(|m| m.name.clone()))
            .unwrap_or_default();
        let class = self
            .store
            .edges_incoming(&[NodeId(method)])
            .ok()
