                edges
                    .iter()
                    .find(|e| e.kind == "Declares")
                    .map(|e| e.from_id.get())
            })
            .and_then(|cid| {
                d.name_of
                    .get(&cid)
                    .cloned()
                    .or_else(|| self.store.get_node(NodeId(cid)).ok().flatten().map(|n| n.name))
            });
        match class {
            Some(c) => format!("{}::{}", c, raw),
            None => raw,
        }
    }
